trace_id = pathlib.Path('/home/user/myproject/output.log').read_text(encoding='utf-8').strip().split(': ', 1)[1]
run_id = os.environ['ZEALT_RUN_ID']
base = os.environ['LANGFUSE_BASE_URL'].rstrip('/')
resp = requests.get(f'{base}/api/public/traces/{trace_id}', auth=(os.environ['LANGFUSE_PUBLIC_KEY'], os.environ['LANGFUSE_SECRET_KEY']), timeout=30)
resp.raise_for_status()
trace = resp.json()
raw_values = [
    'ada.lovelace@example.com', '415-555-2671', '4111-1111-1111-1111',
    'support.agent@example.org', '212.555.0198', '5500 0000 0000 0004',
]
tokens = ['[REDACTED EMAIL]', '[REDACTED PHONE]', '[REDACTED CREDIT CARD]']
failures = []
if trace.get('name') != f'mask-demo-{run_id}':
    failures.append(f"trace name was {trace.get('name')!r}")
for field in ['input', 'output']:
    text = json.dumps(trace.get(field), sort_keys=True)
    for token in tokens:
        if token not in text:
            failures.append(f'trace {field} missing {token}')
    for raw in raw_values:
        if raw in text:
            failures.append(f'trace {field} leaked {raw}')
gens = [o for o in trace.get('observations', []) if o.get('type') == 'GENERATION']
if not gens:
    failures.append('no GENERATION observation found')
else:
    gen_ok = False
    for gen in gens:
        gen_text = json.dumps({'input': gen.get('input'), 'output': gen.get('output')}, sort_keys=True)
        if any(token in gen_text for token in tokens) and not any(raw in gen_text for raw in raw_values):
            gen_ok = True
    if not gen_ok:
        failures.append('no generation had redaction token(s) without raw PII')
full_trace_text = json.dumps(trace, sort_keys=True)
for raw in raw_values:
    if raw in full_trace_text:
        failures.append(f'full trace leaked {raw}')
if failures:
    print('FAIL')
    for f in failures:
        print('-', f)
    sys.exit(1)
print('PASS')
print('trace_id', trace_id)
print('trace_name', trace.get('name'))
print('generation_count', len(gens))
